import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import { Truck, MapPin, Phone, User, Camera, CheckCircle, XCircle, Navigation } from 'lucide-react';
import toast from 'react-hot-toast';
import dispatchService from '../../services/dispatchService';
import StatusBadge from '../../components/datadisplay/StatusBadge';
import ConfirmDialog from '../../components/feedback/ConfirmDialog';

const AssignedDeliveries = () => {
    const [activeTab, setActiveTab] = useState('active');
    const [selectedDelivery, setSelectedDelivery] = useState(null);
    const [confirmAction, setConfirmAction] = useState(null);
    const [proofImage, setProofImage] = useState(null);
    const queryClient = useQueryClient();

    const { data, isLoading } = useQuery({
        queryKey: ['dispatch-deliveries', activeTab],
        queryFn: () => dispatchService.getMyDeliveries({
            status: activeTab === 'active' ? undefined : activeTab
        })
    });

    const statusMutation = useMutation({
        mutationFn: ({ assignmentId, data }) => dispatchService.updateDeliveryStatus(assignmentId, data),
        onSuccess: () => {
            toast.success('Delivery status updated');
            queryClient.invalidateQueries(['dispatch-deliveries']);
            setConfirmAction(null);
            setSelectedDelivery(null);
            setProofImage(null);
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Failed to update status');
        }
    });

    const tabs = [
        { key: 'active', label: 'Active', icon: Truck },
        { key: 'assigned', label: 'New', icon: Package },
        { key: 'in_transit', label: 'In Transit', icon: Navigation },
        { key: 'delivered', label: 'Delivered', icon: CheckCircle },
    ];

    const getNextAction = (status) => {
        const actions = {
            assigned: { action: 'picked_up', label: 'Pick Up', color: 'bg-indigo-600 hover:bg-indigo-700' },
            picked_up: { action: 'in_transit', label: 'Start Delivery', color: 'bg-amber-600 hover:bg-amber-700' },
            in_transit: { action: 'delivered', label: 'Complete Delivery', color: 'bg-emerald-600 hover:bg-emerald-700' }
        };
        return actions[status];
    };

    const handleStatusUpdate = (assignmentId, newStatus) => {
        const data = { status: newStatus };

        if (newStatus === 'delivered') {
            data.proofOfDeliveryUrl = proofImage;
            data.recipientName = selectedDelivery?.customerFirstName + ' ' + selectedDelivery?.customerLastName;
        }

        statusMutation.mutate({ assignmentId, data });
    };

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">My Deliveries</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Manage your assigned deliveries
                </p>
            </div>

            {/* Tabs */}
            <div className="flex gap-2 flex-wrap">
                {tabs.map((tab) => (
                    <button
                        key={tab.key}
                        onClick={() => setActiveTab(tab.key)}
                        className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${activeTab === tab.key
                                ? 'bg-teal-600 text-white shadow-lg'
                                : 'bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 border border-gray-200 dark:border-gray-700'
                            }`}
                    >
                        <tab.icon className="h-4 w-4" />
                        {tab.label}
                    </button>
                ))}
            </div>

            {/* Deliveries List */}
            <div className="space-y-4">
                {isLoading ? (
                    <div className="text-center py-12">
                        <div className="w-8 h-8 border-2 border-teal-500 border-t-transparent rounded-full animate-spin mx-auto" />
                    </div>
                ) : data?.recentAssignments?.length === 0 ? (
                    <div className="text-center py-12 bg-white dark:bg-gray-800 rounded-xl">
                        <Truck className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                        <p className="text-gray-500 dark:text-gray-400">No deliveries in this queue</p>
                    </div>
                ) : (
                    <AnimatePresence>
                        {data?.recentAssignments?.map((assignment, index) => (
                            <motion.div
                                key={assignment.id}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                exit={{ opacity: 0, x: -100 }}
                                transition={{ delay: index * 0.05 }}
                                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6"
                            >
                                <div className="flex flex-col lg:flex-row gap-6">
                                    {/* Product & Customer Info */}
                                    <div className="flex-1 space-y-4">
                                        <div className="flex items-start gap-4">
                                            <div className="h-16 w-16 rounded-lg bg-gray-100 dark:bg-gray-700 overflow-hidden flex-shrink-0">
                                                {assignment.productImage ? (
                                                    <img src={assignment.productImage} alt={assignment.productName} className="h-full w-full object-cover" />
                                                ) : (
                                                    <Package className="h-full w-full p-3 text-gray-400" />
                                                )}
                                            </div>
                                            <div>
                                                <h3 className="font-semibold text-gray-900 dark:text-white">
                                                    {assignment.productName}
                                                </h3>
                                                <StatusBadge status={assignment.status} className="mt-1" />
                                            </div>
                                        </div>

                                        {/* Customer Details */}
                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-4 bg-gray-50 dark:bg-gray-900 rounded-lg">
                                            <div className="flex items-center gap-2 text-sm">
                                                <User className="h-4 w-4 text-gray-400" />
                                                <span className="text-gray-600 dark:text-gray-400">
                                                    {assignment.customerFirstName} {assignment.customerLastName}
                                                </span>
                                            </div>
                                            <div className="flex items-center gap-2 text-sm">
                                                <Phone className="h-4 w-4 text-gray-400" />
                                                <span className="text-gray-600 dark:text-gray-400">
                                                    {assignment.customerPhone}
                                                </span>
                                            </div>
                                            <div className="flex items-start gap-2 text-sm sm:col-span-2">
                                                <MapPin className="h-4 w-4 text-gray-400 mt-0.5" />
                                                <span className="text-gray-600 dark:text-gray-400">
                                                    {assignment.customerAddress}, {assignment.customerCity}, {assignment.customerState}
                                                </span>
                                            </div>
                                        </div>
                                    </div>

                                    {/* Actions */}
                                    <div className="flex flex-col items-end justify-between gap-4">
                                        <div className="text-right">
                                            <p className="text-sm text-gray-500">Delivery Fee</p>
                                            <p className="text-2xl font-bold text-teal-600">
                                                ${assignment.deliveryFee?.toFixed(2) || '0.00'}
                                            </p>
                                        </div>

                                        {getNextAction(assignment.status)?.action && (
                                            <button
                                                onClick={() => {
                                                    setSelectedDelivery(assignment);
                                                    if (getNextAction(assignment.status).action === 'delivered') {
                                                        setConfirmAction({
                                                            assignmentId: assignment.id,
                                                            status: 'delivered',
                                                            label: 'Complete Delivery'
                                                        });
                                                    } else {
                                                        handleStatusUpdate(assignment.id, getNextAction(assignment.status).action);
                                                    }
                                                }}
                                                className={`px-4 py-2 text-white rounded-lg font-medium transition-colors ${getNextAction(assignment.status).color
                                                    }`}
                                            >
                                                {getNextAction(assignment.status).label}
                                            </button>
                                        )}

                                        {['assigned', 'picked_up'].includes(assignment.status) && (
                                            <button
                                                onClick={() => setConfirmAction({
                                                    assignmentId: assignment.id,
                                                    status: 'cancelled',
                                                    label: 'Cancel Delivery'
                                                })}
                                                className="px-4 py-2 text-rose-600 hover:bg-rose-50 rounded-lg font-medium transition-colors"
                                            >
                                                <XCircle className="h-5 w-5" />
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </motion.div>
                        ))}
                    </AnimatePresence>
                )}
            </div>

            {/* Proof of Delivery Modal */}
            <AnimatePresence>
                {confirmAction?.status === 'delivered' && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                        <motion.div
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            className="fixed inset-0 bg-black/50"
                            onClick={() => setConfirmAction(null)}
                        />

                        <motion.div
                            initial={{ scale: 0.95 }}
                            animate={{ scale: 1 }}
                            exit={{ scale: 0.95 }}
                            className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-md p-6"
                        >
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                                Proof of Delivery
                            </h3>

                            <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
                                Please upload a photo as proof of delivery
                            </p>

                            {/* Image Upload Area */}
                            <div className="mb-4">
                                <label className="block w-full aspect-video rounded-lg border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-teal-500 transition-colors cursor-pointer">
                                    <input
                                        type="file"
                                        accept="image/*"
                                        className="hidden"
                                        onChange={(e) => {
                                            const file = e.target.files[0];
                                            if (file) {
                                                // In production, upload to cloud storage and get URL
                                                const reader = new FileReader();
                                                reader.onload = (e) => setProofImage(e.target.result);
                                                reader.readAsDataURL(file);
                                            }
                                        }}
                                    />
                                    {proofImage ? (
                                        <img src={proofImage} alt="Proof" className="w-full h-full object-cover rounded-lg" />
                                    ) : (
                                        <div className="flex flex-col items-center justify-center h-full">
                                            <Camera className="h-8 w-8 text-gray-400 mb-2" />
                                            <span className="text-sm text-gray-500">Click to upload photo</span>
                                        </div>
                                    )}
                                </label>
                            </div>

                            <div className="flex gap-3">
                                <button
                                    onClick={() => setConfirmAction(null)}
                                    className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={() => handleStatusUpdate(confirmAction.assignmentId, 'delivered')}
                                    disabled={!proofImage || statusMutation.isLoading}
                                    className="flex-1 px-4 py-2 bg-emerald-600 text-white rounded-lg font-medium hover:bg-emerald-700 disabled:opacity-50 transition-colors"
                                >
                                    {statusMutation.isLoading ? 'Processing...' : 'Confirm Delivery'}
                                </button>
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            {/* General Confirmation Dialog */}
            <ConfirmDialog
                isOpen={!!confirmAction && confirmAction.status !== 'delivered'}
                onClose={() => setConfirmAction(null)}
                onConfirm={() => handleStatusUpdate(confirmAction.assignmentId, confirmAction.status)}
                title="Update Delivery Status"
                message={`Are you sure you want to ${confirmAction?.label?.toLowerCase()}?`}
                confirmText="Confirm"
                loading={statusMutation.isLoading}
            />
        </div>
    );
};

export default AssignedDeliveries;
